import {MAX_LEVEL,levelById} from './levels.js';
const KEY='bean-dash-profile-v3';
export const OUTFITS=[{id:'dash',name:'Dash',description:'The original street runner',unlock:1,color:'#ff725e'},{id:'nova',name:'Nova',description:'A fresh perspective',unlock:5,color:'#9279ff'},{id:'ace',name:'Ace',description:'Built for the podium',unlock:15,color:'#44c9b4'},{id:'gold',name:'Gold Rush',description:'For the long-distance legends',unlock:30,color:'#ffcb66'}];
const blank=()=>({version:3,id:globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2),name:'Guest Runner',color:'#ff725e',outfit:'dash',unlocked:1,selected:1,crowns:0,races:0,coins:0,xp:0,bests:{},medals:{},sound:true,quality:'auto',tutorial:false});
export function medalFor(level,seconds){const l=levelById(level);return seconds<=l.gold?3:seconds<=l.silver?2:1}
export function createProfileStore(storage){let persistent=true,p=blank();try{const saved=JSON.parse(storage.getItem(KEY)||storage.getItem('bean-dash-profile-v2')||'null');if(saved){p={...p,...saved,version:3};if(saved.version===2){p.legacyBests=saved.bests||{};p.bests={};p.medals={}};p.unlocked=Math.min(MAX_LEVEL,Math.max(1,Number(p.unlocked)||1));p.selected=Math.min(p.unlocked,Math.max(1,Number(p.selected)||1));p.bests=typeof p.bests==='object'&&p.bests?p.bests:{};p.medals=typeof p.medals==='object'&&p.medals?p.medals:{};if(!OUTFITS.some(o=>o.id===p.outfit))p.outfit='dash'}storage.setItem(KEY,JSON.stringify(p))}catch{persistent=false}
 const save=()=>{try{storage.setItem(KEY,JSON.stringify(p))}catch{persistent=false}};
 return {get:()=>structuredClone(p),isPersistent:()=>persistent,update(patch){for(const k of ['name','color','sound','selected','outfit','quality','tutorial'])if(k in patch)p[k]=patch[k];p.name=String(p.name).slice(0,20);p.selected=Math.min(p.unlocked,Math.max(1,Number(p.selected)||1));if(!OUTFITS.some(o=>o.id===p.outfit&&o.unlock<=p.unlocked))p.outfit='dash';save()},record(level,seconds,win,{coins=0,rank=0,falls=0}={}){p.races++;const previous=p.bests[level],medal=win?medalFor(level,seconds):0,first=win&&!previous;const reward=Math.min(500,Math.max(0,Number(coins)||0))+(win?20+level*2:0);p.coins+=reward;const xp=win?100+level*5+medal*25+(falls===0?50:0):20;p.xp+=xp;if(win){p.unlocked=Math.max(p.unlocked,Math.min(MAX_LEVEL,level+1));if(Number.isFinite(seconds)&&seconds>0)p.bests[level]=Math.min(p.bests[level]||Infinity,seconds);p.medals[level]=Math.max(p.medals[level]||0,medal);if(rank===1)p.crowns++}save();return {medal,reward,xp,newBest:win&&(!previous||seconds<previous),first,newOutfit:win?OUTFITS.find(o=>o.unlock===level+1):null}},reset(){p=blank();save()}};
}
